SELECT 'market_capture' AS section, capture_id,capture_kind,status,reason,canonical,finality,from_block,to_block,protocol_rows,quote_rows,request_rows,finalization_rows,claim_rows,hex(evidence_root_hash) AS evidence_hash FROM crypto_market_info_lst.lst_capture FINAL WHERE capture_id='fb2587fe-33a4-44b2-b627-d1f28d7dadc3' FORMAT JSONEachRow;
SELECT 'market_quote' AS section, route_id,toString(purchase_budget_usdt_raw) AS usdt_raw,buy_status,buy_reason,conversion_status,conversion_reason,exit_status,exit_reason,hedge_status,hedge_reason,timing_status,reason,toString(buy_lst_out_raw) AS lst_raw,toString(nominal_redeem_eth_wei) AS redeem_wei FROM crypto_market_info_lst.lst_quote_observation FINAL WHERE capture_id='fb2587fe-33a4-44b2-b627-d1f28d7dadc3' ORDER BY purchase_budget_usdt_raw,route_id FORMAT JSONEachRow;
SELECT 'protocol' AS section, state_status,reason,block_number,hex(block_hash) AS block_hash,queue_paused,bunker_active FROM crypto_market_info_lst.lst_protocol_state FINAL WHERE capture_id='fb2587fe-33a4-44b2-b627-d1f28d7dadc3' FORMAT JSONEachRow;
SELECT 'historical_capture' AS section, capture_id,started_at,status,reason,canonical,finality,from_block,to_block,request_rows,finalization_rows,claim_rows,hex(evidence_root_hash) AS evidence_hash FROM crypto_market_info_lst.lst_capture FINAL WHERE capture_kind='logs' AND capture_mode='backfill' AND from_block=26104300 AND to_block=26104811 ORDER BY started_at FORMAT JSONEachRow;
